596. pub open spec fn map_min_value(m: Map<NodeId, nat>, idx: nat) -> nat
597.     decreases idx,
598. {
599.     if idx === 0 {
600.         m.index(0)
601.     } else {
602.         min(map_min_value(m, (idx - 1) as nat), m.index(idx))
