606. proof fn map_min_value_smallest(m: Map<NodeId, nat>, idx: nat)
607.     requires
608.         forall|i| 0 <= i <= idx ==> m.contains_key(i),
609.     ensures
610.         forall|n| 0 <= n <= idx as nat ==> map_min_value(m, idx) <= m.index(n),
611.         map_contains_value(m, map_min_value(m, idx)),
612.     decreases idx,
613. {
614.     if idx == 0 {
615.         assert(m.contains_key(0));
616.     } else {
617.         map_min_value_smallest(m, (idx - 1) as nat);
618.         if m.index(idx) < map_min_value(m, (idx - 1) as nat) {
619.             assert(m.contains_key(idx));
620.         }
621.     }
622. }
